import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 6 Smash-and-grab","description":"学习 一般过去时的被动语态，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 6 Smash-and-grab","description":"学习 一般过去时的被动语态，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 一般过去时的被动语态，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 5 The facts","link":"/life/english/new-concept/book-3/unit-01/lesson-005"},"next":{"text":"第三册：培养技能 · Lesson 7 Mutilated ladies","link":"/life/english/new-concept/book-3/unit-01/lesson-007"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 5 The facts","link":"/life/english/new-concept/book-3/unit-01/lesson-005"},"next":{"text":"第三册：培养技能 · Lesson 7 Mutilated ladies","link":"/life/english/new-concept/book-3/unit-01/lesson-007"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-006.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-006.md"}'),s={name:"life/english/new-concept/book-3/unit-01/lesson-006.md"};function i(l,e,r,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-6-smash-and-grab" tabindex="-1">第三册：培养技能 · Lesson 6 Smash-and-grab <a class="header-anchor" href="#第三册-培养技能-·-lesson-6-smash-and-grab" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 6 Smash-and-grab&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以突发盗窃的观察和安全描述为背景，练习按时间顺序记录可见动作。关注动作承受者时使用被动语态，谈到未知行为人时不凭空补出身份。学习把一段事件描述写得简洁、可核实，并能区分被损坏的物品和实施动作的人。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>shatter</td><td>/ˈʃætə/</td><td>v.</td><td>使粉碎</td><td>shatter a window</td></tr><tr><td>display</td><td>/dɪˈspleɪ/</td><td>n.</td><td>陈列</td><td>a window display</td></tr><tr><td>alarm</td><td>/əˈlɑːm/</td><td>n.</td><td>警报器</td><td>set off an alarm</td></tr><tr><td>escape</td><td>/ɪˈskeɪp/</td><td>v.</td><td>逃离</td><td>escape through a door</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>in broad daylight — 在光天化日之下</li><li>make off with — 偷走某物后逃离</li></ul><h2 id="语法讲解-一般过去时的被动语态" tabindex="-1">语法讲解：一般过去时的被动语态 <a class="header-anchor" href="#语法讲解-一般过去时的被动语态" aria-label="Permalink to &quot;语法讲解：一般过去时的被动语态&quot;">​</a></h2><p>被动结构由 be 的适当形式加过去分词组成，过去事件常用 was 或 were。原句宾语移到主语位置，动作实施者若未知、不重要或上下文已明，可不写 by 短语。只有能带宾语的及物用法通常能够这样转换，happen、arrive 等不能直接变为被动。被动不等于刻意隐藏责任；如责任人是报道重点，主动句更清楚。过去分词也可能作形容词，判断时需结合是否强调一个发生的动作。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Two display cases were damaged before the alarm was raised.</p></blockquote><p>警报发出前，两个展示柜遭到了损坏。</p><p>were damaged 与 was raised 均为过去时被动；cases 为复数，alarm 为单数。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The accident was happened 不成立，因为 happen 不带直接宾语；应写 The accident happened。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读示范，检查 was heard 与 was found 中 was 是否轻读，同时保留 heard、found 的关键信息重音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A loud crash was heard at noon. One cabinet was found open near the entrance. Staff checked the camera recordings later that day.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句虚构店铺事件记录，只陈述观察到的事实，不猜测嫌疑人身份。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>前两句聚焦所听所见，末句主动说明工作人员的后续行动。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>把 Someone broke the glass 改为被动，省略行为人。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The glass was broken.</p><p><strong>解析：</strong> glass 作主语，break 的过去分词为 broken。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句能确定是谁损坏展示柜的吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 被动句没有提供行为人。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：The doors ___ locked at nine.（was/were）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> 主语 doors 为复数。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般过去时的被动语态。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-005">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-007">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(s,[["render",i]]);export{u as __pageData,b as default};
